class PaymentService:
  try:
    @staticmethod
    def _normalize_payment_method(payment_method: Any) -> str:
        if hasattr(payment_method, "value"):
            return str(payment_method.value).strip().lower()
        return str(payment_method).strip().lower()

    @staticmethod
    def _normalize_status(value: Any) -> str:
        if hasattr(value, "value"):
            return str(value.value).strip().lower()
        normalized = str(value).strip().lower()
        if "." in normalized:
            normalized = normalized.split(".")[-1]
        return normalized

    @staticmethod
    def _to_uuid(value: Any, field_name: str) -> uuid.UUID:
        if isinstance(value, uuid.UUID):
            return value
        try:
            return uuid.UUID(str(value))
        except Exception as exc:
            raise HTTPException(status_code=400, detail=f"Invalid {field_name}: {value}") from exc

    @staticmethod
    def _to_float(value: Any) -> float:
        if isinstance(value, Decimal):
            return float(value)
        return float(value)

    @staticmethod
    def _schedule_broadcast(event_id: str, message: dict) -> None:
        try:
            loop = asyncio.get_running_loop()
            loop.create_task(manager.broadcast_to_event(event_id=event_id, message=message))
        except RuntimeError:
            logger.warning("No running event loop for WebSocket broadcast")
        except Exception as exc:
            logger.warning("WebSocket broadcast scheduling failed: %s", exc)

    @staticmethod
    def _get_payment_method_enum(payment_method: str) -> PaymentMethod:
        try:
            return PaymentMethod(payment_method)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=f"Invalid payment method: {payment_method}") from exc

    @staticmethod
    def _create_audit_log(
        payment_id: uuid.UUID,
        event_type: str,
        old_status: Optional[str],
        new_status: str,
        details: str,
    ) -> PaymentAuditLog:
        return PaymentAuditLog(
            payment_id=payment_id,
            event_type=event_type,
            old_status=old_status,
            new_status=new_status,
            details=details,
        )

    @staticmethod
    def create_booking_with_payment(
        db: Session,
        user_id: Any,
        event_id: Any,
        seat_id: Any,
        payment_method: str,
        payment_details: dict,
        hold_token: str,
        idempotency_key: str = None,
    ) -> Tuple[Booking, Optional[Payment], str]:
        user_uuid = PaymentService._to_uuid(user_id, "user_id")
        event_uuid = PaymentService._to_uuid(event_id, "event_id")
        seat_uuid = PaymentService._to_uuid(seat_id, "seat_id")
        payment_method_value = PaymentService._normalize_payment_method(payment_method)
        payment_method_enum = PaymentService._get_payment_method_enum(payment_method_value)
        lock_key = f"booking:{event_uuid}:{seat_uuid}"

        with tracer.start_as_current_span("booking.create_with_payment") as span:
            span.set_attribute("app.user_id", str(user_uuid))
            span.set_attribute("app.event_id", str(event_uuid))
            span.set_attribute("app.seat_id", str(seat_uuid))
            span.set_attribute("app.payment_method", payment_method_value)
            span.set_attribute("app.has_hold_token", bool(hold_token))
            span.set_attribute("app.idempotent", bool(idempotency_key))

            try:
                if idempotency_key:
                    with tracer.start_as_current_span("booking.check_idempotency"):
                        existing_booking = (
                            db.query(Booking)
                            .filter(Booking.idempotency_key == idempotency_key)
                            .first()
                        )
                        if existing_booking:
                            span.set_attribute("app.result", "duplicate")
                            return existing_booking, existing_booking.payment, "duplicate"

                with tracer.start_as_current_span("booking.validate_hold"):
                    hold = HoldService.validate_hold(
                        hold_token=hold_token,
                        user_id=str(user_uuid),
                        event_id=str(event_uuid),
                        seat_id=str(seat_uuid),
                    )
                    if not hold:
                        span.set_status(Status(StatusCode.ERROR, "Seat hold is missing or expired"))
                        raise HTTPException(status_code=409, detail="Seat hold is missing or expired")

                with tracer.start_as_current_span("booking.prepare_records"):
                    with acquire_lock(lock_key, timeout=10):
                        seat = (
                            db.query(Seat)
                            .filter(and_(Seat.seat_id == seat_uuid, Seat.event_id == event_uuid))
                            .with_for_update()
                            .first()
                        )

                        if not seat:
                            span.set_status(Status(StatusCode.ERROR, "Seat not found"))
                            raise HTTPException(status_code=404, detail="Seat not found")

                        seat_status_value = PaymentService._normalize_status(seat.status)
                        if seat_status_value == "booked":
                            span.set_status(Status(StatusCode.ERROR, "Seat is already booked"))
                            raise HTTPException(status_code=409, detail="Seat is already booked")
                        if seat_status_value != "available":
                            span.set_status(Status(StatusCode.ERROR, f"Seat is not available: {seat_status_value}"))
                            raise HTTPException(status_code=409, detail=f"Seat is not available: {seat_status_value}")

                        event = db.query(Event).filter(Event.event_id == event_uuid).first()
                        if not event:
                            span.set_status(Status(StatusCode.ERROR, "Event not found"))
                            raise HTTPException(status_code=404, detail="Event not found")

                        booking = Booking(
                            user_id=user_uuid,
                            event_id=event_uuid,
                            seat_id=seat_uuid,
                            total_amount=seat.price,
                            status=BookingStatus("pending_payment"),
                            idempotency_key=idempotency_key,
                        )
                        db.add(booking)
                        db.flush()

                        payment = Payment(
                            booking_id=booking.booking_id,
                            user_id=user_uuid,
                            amount=seat.price,
                            currency="USD",
                            payment_method=payment_method_enum,
                            status=PaymentStatus("pending"),
                        )
                        db.add(payment)
                        db.flush()

                        db.add(
                            PaymentService._create_audit_log(
                                payment_id=payment.payment_id,
                                event_type="initiated",
                                old_status=None,
                                new_status="pending",
                                details="Payment initiated",
                            )
                        )

                        booking.status = BookingStatus("payment_processing")
                        payment.status = PaymentStatus("processing")
                        db.flush()

                PaymentService._schedule_broadcast(
                    event_id=str(event_uuid),
                    message={
                        "type": "seat_update",
                        "action": "payment_processing",
                        "event_id": str(event_uuid),
                        "seat_id": str(seat_uuid),
                        "seat_number": seat.seat_number,
                        "status": "held",
                        "held_by": str(user_uuid),
                        "timestamp": datetime.utcnow().isoformat(),
                    },
                )

                with tracer.start_as_current_span("payment_gateway.process") as payment_span:
                    payment_span.set_attribute("payment.gateway.name", "mock")
                    payment_span.set_attribute("payment.gateway.mode", "in_process")
                    payment_span.set_attribute("payment.amount", PaymentService._to_float(seat.price))
                    payment_span.set_attribute("payment.currency", "USD")
                    payment_span.set_attribute("payment.method", payment_method_value)

                    success, gateway_response = MockPaymentGateway.process_payment(
                        amount=PaymentService._to_float(seat.price),
                        currency="USD",
                        payment_method=payment_method_value,
                        payment_details=payment_details,
                    )

                    payment_span.set_attribute("payment.gateway.success", bool(success))
                    if not success:
                        payment_span.set_status(Status(StatusCode.ERROR, gateway_response.get("error", "Payment failed")))

                with tracer.start_as_current_span("booking.finalize"):
                    with acquire_lock(lock_key, timeout=10):
                        hold = HoldService.validate_hold(
                            hold_token=hold_token,
                            user_id=str(user_uuid),
                            event_id=str(event_uuid),
                            seat_id=str(seat_uuid),
                        )
                        if not hold:
                            span.set_status(Status(StatusCode.ERROR, "Seat hold expired during payment"))
                            raise HTTPException(status_code=409, detail="Seat hold expired during payment")

                        seat = (
                            db.query(Seat)
                            .filter(and_(Seat.seat_id == seat_uuid, Seat.event_id == event_uuid))
                            .with_for_update()
                            .first()
                        )
                        payment = db.query(Payment).filter(Payment.payment_id == payment.payment_id).first()
                        booking = db.query(Booking).filter(Booking.booking_id == booking.booking_id).first()

                        if not seat or not payment or not booking:
                            span.set_status(Status(StatusCode.ERROR, "Booking state could not be finalized"))
                            raise HTTPException(status_code=500, detail="Booking state could not be finalized")

                        if success:
                            payment.status = PaymentStatus("completed")
                            payment.gateway_transaction_id = gateway_response.get("transaction_id")
                            payment.gateway_response = json.dumps(gateway_response)
                            payment.completed_at = datetime.utcnow()

                            if payment_method_value in {"credit_card", "debit_card"}:
                                payment.card_last4 = gateway_response.get("card_last4")
                                payment.card_brand = gateway_response.get("card_brand")

                            booking.status = BookingStatus("confirmed")
                            seat.status = SeatStatus("booked")
                            seat.booked_by = user_uuid
                            seat.booked_at = datetime.utcnow()

                            db.add(
                                PaymentService._create_audit_log(
                                    payment_id=payment.payment_id,
                                    event_type="completed",
                                    old_status="processing",
                                    new_status="completed",
                                    details=f"Payment successful: {gateway_response.get('transaction_id')}",
                                )
                            )

                            db.commit()
                            db.refresh(booking)
                            db.refresh(payment)
                            HoldService.release_hold(hold_token)

                            PaymentService._schedule_broadcast(
                                event_id=str(event_uuid),
                                message={
                                    "type": "seat_update",
                                    "action": "booked",
                                    "event_id": str(event_uuid),
                                    "seat_id": str(seat_uuid),
                                    "seat_number": seat.seat_number,
                                    "status": "booked",
                                    "booked_by": str(user_uuid),
                                    "booking_id": str(booking.booking_id),
                                    "timestamp": datetime.utcnow().isoformat(),
                                },
                            )

                            span.set_attribute("app.result", "success")
                            span.set_attribute("app.booking_id", str(booking.booking_id))
                            span.set_attribute("app.payment_id", str(payment.payment_id))
                            return booking, payment, "success"

                        payment.status = PaymentStatus("failed")
                        payment.gateway_response = json.dumps(gateway_response)
                        payment.failed_at = datetime.utcnow()
                        payment.failure_reason = gateway_response.get("error", "Payment failed")
                        booking.status = BookingStatus("failed")

                        db.add(
                            PaymentService._create_audit_log(
                                payment_id=payment.payment_id,
                                event_type="failed",
                                old_status="processing",
                                new_status="failed",
                                details=f"Payment failed: {gateway_response.get('error')}",
                            )
                        )

                        db.commit()
                        db.refresh(booking)
                        db.refresh(payment)
                        HoldService.release_hold(hold_token)

                        PaymentService._schedule_broadcast(
                            event_id=str(event_uuid),
                            message={
                                "type": "seat_update",
                                "action": "released",
                                "event_id": str(event_uuid),
                                "seat_id": str(seat_uuid),
                                "seat_number": seat.seat_number,
                                "status": "available",
                                "timestamp": datetime.utcnow().isoformat(),
                            },
                        )

                        span.set_status(Status(StatusCode.ERROR, gateway_response.get("error", "Payment failed")))
                        raise HTTPException(
                            status_code=402,
                            detail={
                                "message": "Payment failed",
                                "error": gateway_response.get("error"),
                                "error_code": gateway_response.get("error_code"),
                                "booking_id": str(booking.booking_id),
                                "payment_id": str(payment.payment_id),
                            },
                        )

            except HTTPException as exc:
                db.rollback()
                span.record_exception(exc)
                span.set_status(Status(StatusCode.ERROR, str(exc.detail)))
                raise
            except Exception as exc:
                db.rollback()
                span.record_exception(exc)
                span.set_status(Status(StatusCode.ERROR, str(exc)))
                logger.exception("Booking transaction failed | type=%s repr=%r", type(exc).__name__, exc)
                raise HTTPException(status_code=500, detail=f"Booking failed: {type(exc).__name__}: {str(exc)}")

    @staticmethod
    async def process_refund(db: Session, booking_id: Any, user_id: Any, reason: str):
        booking_uuid = PaymentService._to_uuid(booking_id, "booking_id")
        user_uuid = PaymentService._to_uuid(user_id, "user_id")

        with tracer.start_as_current_span("booking.process_refund") as span:
            span.set_attribute("app.booking_id", str(booking_uuid))
            span.set_attribute("app.user_id", str(user_uuid))

            try:
                booking = db.query(Booking).filter(Booking.booking_id == booking_uuid).first()
                if not booking:
                    raise HTTPException(status_code=404, detail="Booking not found")

                if booking.user_id != user_uuid:
                    raise HTTPException(status_code=403, detail="Not your booking")

                booking_status_value = PaymentService._normalize_status(booking.status)
                if booking_status_value != "confirmed":
                    raise HTTPException(status_code=400, detail=f"Cannot refund booking in {booking_status_value} status")

                payment = booking.payment
                if not payment:
                    raise HTTPException(status_code=400, detail="No payment found")

                payment_status_value = PaymentService._normalize_status(payment.status)
                if payment_status_value != "completed":
                    raise HTTPException(status_code=400, detail="No completed payment found")

                with tracer.start_as_current_span("payment_gateway.refund") as refund_span:
                    success, refund_response = MockPaymentGateway.process_refund(
                        transaction_id=payment.gateway_transaction_id,
                        amount=PaymentService._to_float(payment.amount),
                        reason=reason,
                    )
                    refund_span.set_attribute("payment.gateway.success", bool(success))
                    if not success:
                        refund_span.set_status(Status(StatusCode.ERROR, refund_response.get("error", "Refund failed")))

                if not success:
                    raise HTTPException(
                        status_code=500,
                        detail=f"Refund processing failed: {refund_response.get('error')}",
                    )

                payment.status = PaymentStatus("refunded")
                payment.gateway_response = json.dumps(
                    {
                        "payment": json.loads(payment.gateway_response) if payment.gateway_response else None,
                        "refund": refund_response,
                    }
                )

                booking.status = BookingStatus("refunded")
                booking.updated_at = datetime.utcnow()

                seat = db.query(Seat).filter(Seat.seat_id == booking.seat_id).first()
                seat_number = None
                if seat:
                    seat_number = seat.seat_number
                    seat.status = SeatStatus("available")
                    seat.booked_by = None
                    seat.booked_at = None

                db.add(
                    PaymentService._create_audit_log(
                        payment_id=payment.payment_id,
                        event_type="refunded",
                        old_status="completed",
                        new_status="refunded",
                        details=f"Refund processed: {reason}",
                    )
                )

                db.commit()
                db.refresh(booking)
                db.refresh(payment)

                await manager.broadcast_to_event(
                    event_id=str(booking.event_id),
                    message={
                        "type": "seat_update",
                        "action": "refunded",
                        "event_id": str(booking.event_id),
                        "seat_id": str(booking.seat_id),
                        "seat_number": seat_number,
                        "status": "available",
                        "refund_id": refund_response.get("refund_id"),
                        "timestamp": datetime.utcnow().isoformat(),
                    },
                )

                return {
                    "booking_id": str(booking.booking_id),
                    "payment_id": str(payment.payment_id),
                    "refund_amount": PaymentService._to_float(payment.amount),
                    "status": "refunded",
                    "refund_transaction_id": refund_response.get("refund_id"),
                    "seat_released": True,
                    "message": "Refund processed successfully and seat has been released",
                }

            except HTTPException as exc:
                db.rollback()
                span.record_exception(exc)
                span.set_status(Status(StatusCode.ERROR, str(exc.detail)))
                raise
            except Exception as exc:
                db.rollback()
                span.record_exception(exc)
                span.set_status(Status(StatusCode.ERROR, str(exc)))
                logger.exception("Refund transaction failed | type=%s repr=%r", type(exc).__name__, exc)
                raise HTTPException(status_code=500, detail=f"Refund failed: {type(exc).__name__}: {str(exc)}")
  except Exception:
      payment_outcome = "failure"
      raise
  finally:
      observe_payment_completion_latency(
          time.perf_counter() - payment_started,
          payment_outcome,
      )
